module synchronizer (
    input clk_a,
    input clk_b,
    input arstn,
    input brstn,
    input [3:0] data_in,
    input data_en,
    output reg [3:0] dataout
);

    reg [3:0] data_reg;
    reg [3:0] en_data_reg;
    reg [3:0] en_clap_one;
    reg [3:0] en_clap_two;

    // Update data_reg on posedge clk_a or negedge arstn
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn)
            data_reg <= 4'b0000;
        else
            data_reg <= data_in;
    end

    // Update en_data_reg on posedge clk_a or negedge arstn
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn)
            en_data_reg <= 4'b0000;
        else
            en_data_reg <= data_en ? 4'b1111 : 4'b0000;
    end

    // Update en_clap_one and en_clap_two on posedge clk_b or negedge brstn
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            en_clap_one <= 4'b0000;
            en_clap_two <= 4'b0000;
        end else begin
            en_clap_one <= en_data_reg;
            en_clap_two <= en_clap_one;
        end
    end

    // Assign dataout on posedge clk_b or negedge brstn
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)
            dataout <= 4'b0000;
        else if (en_clap_two != 4'b0000)
            dataout <= data_reg;
        else
            dataout <= dataout;
    end

endmodule
